using System;
using System.Globalization;
using System.Text;
using NWH.WheelController3D;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using LWS.TruckSports;
namespace LWS.TruckBowling.Editor {
public static class BowlingCabRepairAuthoring {
 [MenuItem("Truck Sports/Bowling/Remove Obsolete Cab (preserve scene)")]
 public static void Apply(){if(EditorApplication.isPlaying||EditorApplication.isCompiling)throw new InvalidOperationException("Stopped, compiled Editor required");var scene=EditorSceneManager.OpenScene(BowlingAuthoring.Scene);var match=UnityEngine.Object.FindAnyObjectByType<BowlingMatch>();
  // Verify every replacement exists before deleting any old geometry.
  foreach(var lane in match.lanes){var link=lane.cab.GetComponent<SportsLegacyCabLook>();if(link==null||link.cockpit==null||link.cockpit.GetComponentsInChildren<Renderer>(true).Length==0)throw new Exception("Canonical Taxi interior missing for lane "+lane.index);}
  string physicsBefore=PhysicsSignature(match);int removed=0;foreach(var lane in match.lanes){var old=lane.cab.transform.Find("Inside tiny cab");if(old!=null){UnityEngine.Object.DestroyImmediate(old.gameObject);removed++;}lane.cab.interior=lane.cab.GetComponent<SportsLegacyCabLook>().cockpit.GetComponentsInChildren<Renderer>(true);AlignTruck(lane.truck);lane.cab.exterior=lane.truck.GetComponentsInChildren<Renderer>(true);}
  if(physicsBefore!=PhysicsSignature(match))throw new Exception("Visual repair changed authoritative physics parameters");Validate(match);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("BOWLING_OBSOLETE_CABS_REMOVED count="+removed+"; native Taxi interiors retained; truck meshes aligned; physics parameters unchanged");
 }
 static string PhysicsSignature(BowlingMatch match){var text=new StringBuilder();foreach(var lane in match.lanes){var t=lane.truck;var b=t.body;var shape=t.GetComponent<BoxCollider>();text.Append(b.mass.ToString("R",CultureInfo.InvariantCulture)).Append(b.linearDamping.ToString("R",CultureInfo.InvariantCulture)).Append(b.angularDamping.ToString("R",CultureInfo.InvariantCulture)).Append(shape.size).Append(shape.center).Append(AssetDatabase.GetAssetPath(shape.sharedMaterial));foreach(var w in t.wheels)text.Append(w.wheel.radius.ToString("R",CultureInfo.InvariantCulture)).Append(w.wheel.width.ToString("R",CultureInfo.InvariantCulture)).Append(w.wheel.mass.ToString("R",CultureInfo.InvariantCulture)).Append(w.spring.maxLength.ToString("R",CultureInfo.InvariantCulture)).Append(w.spring.maxForce.ToString("R",CultureInfo.InvariantCulture)).Append(w.damper.bumpRate.ToString("R",CultureInfo.InvariantCulture)).Append(w.damper.reboundRate.ToString("R",CultureInfo.InvariantCulture)).Append(AssetDatabase.GetAssetPath(w.FrictionPreset));}return text.ToString();}
 static Bounds LocalMeshBounds(Transform model,Transform body){bool found=false;Bounds bounds=default;foreach(var filter in model.GetComponentsInChildren<MeshFilter>(true)){if(filter.sharedMesh==null)continue;var mesh=filter.sharedMesh.bounds;var matrix=body.worldToLocalMatrix*filter.transform.localToWorldMatrix;for(int i=0;i<8;i++){var sign=new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1);var point=matrix.MultiplyPoint3x4(mesh.center+Vector3.Scale(mesh.extents,sign));if(!found){bounds=new Bounds(point,Vector3.zero);found=true;}else bounds.Encapsulate(point);}}if(!found)throw new Exception("Owned truck mesh missing");return bounds;}
 public static void AlignTruck(BowlingTruck truck){
  string[] names={"Whl HD FL","Whl HD FR","Whl HD RL","Whl HD RR"};bool installed=true;foreach(var w in truck.wheels)installed&=w.wheel.rotatingContainer!=null&&w.wheel.rotatingContainer.GetComponentInChildren<MeshRenderer>()!=null;
  if(!installed){var model=truck.exterior.transform.Find("NWH GR3D visual geometry");if(model==null)throw new Exception("Expected owned NWH visual model");var bounds=LocalMeshBounds(model,truck.transform);float scale=1.25f/Mathf.Max(bounds.size.x,bounds.size.z);model.localScale*=scale;bounds=LocalMeshBounds(model,truck.transform);var delta=new Vector3(-bounds.center.x,-.2f-bounds.min.y,-bounds.center.z);model.position+=truck.transform.TransformVector(delta);
   for(int i=0;i<truck.wheels.Length;i++){var wheel=truck.wheels[i];float radius=wheel.wheel.radius,width=wheel.wheel.width;wheel.FindOrSpawnVisualContainers();var container=wheel.wheel.rotatingContainer;MeshRenderer source=null;foreach(var r in truck.GetComponentsInChildren<MeshRenderer>(true))if(r.name==names[i]){source=r;break;}if(source==null)throw new Exception("Owned wheel mesh missing "+names[i]);source.transform.SetParent(container,true);var size=source.bounds.size;source.transform.localScale=Vector3.Scale(source.transform.localScale,new Vector3(width/size.x,radius*2/size.y,radius*2/size.z));source.transform.position+=container.position-source.bounds.center;wheel.wheel.radius=radius;wheel.wheel.width=width;EditorUtility.SetDirty(wheel);}
  }
  foreach(var renderer in truck.GetComponentsInChildren<MeshRenderer>(true))if(renderer.name=="Wheel visual")UnityEngine.Object.DestroyImmediate(renderer.gameObject);
 }
 public static void Validate(BowlingMatch match){foreach(var lane in match.lanes){var link=lane.cab.GetComponent<SportsLegacyCabLook>();if(lane.cab.transform.Find("Inside tiny cab")!=null||link==null||link.cockpit==null||lane.cab.interior.Length==0)throw new Exception("Bowling obsolete/missing cab in lane "+lane.index);var t=lane.truck;MeshFilter cab=null;foreach(var f in t.exterior.GetComponentsInChildren<MeshFilter>(true))if(f.name=="Cab")cab=f;if(cab==null)throw new Exception("Truck Cab mesh missing");var center=t.transform.InverseTransformPoint(cab.transform.TransformPoint(cab.sharedMesh.bounds.center));if(new Vector2(center.x,center.z).magnitude>1)throw new Exception("Bowling visual model offset from physical chassis "+lane.index+" "+center);foreach(var w in t.wheels)if(w.wheel.rotatingContainer==null||w.wheel.rotatingContainer.GetComponentInChildren<MeshRenderer>()==null)throw new Exception("Native rolling wheel visuals missing");}}
}
}
